import{z as s,x as o,o as t,c as p,q as r,j as n,D as e,d as i,s as l,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"MiFID II RTS 6 算法交易合规","description":"","frontmatter":{"title":"MiFID II RTS 6 算法交易合规","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mifid-ii-rts6.md","filePath":"quant/mifid-ii-rts6.md","lastUpdated":1791413859000}'),d={name:"quant/mifid-ii-rts6.md"};function h(D,E,m,C,u,T){const A=o("Mermaid");return t(),p("div",null,[E[2]||(E[2]=r('<h1 id="mifid-ii-rts-6-算法交易合规" tabindex="-1">MiFID II RTS 6 算法交易合规 <a class="header-anchor" href="#mifid-ii-rts-6-算法交易合规" aria-label="Permalink to &quot;MiFID II RTS 6 算法交易合规&quot;">​</a></h1><div class="epigraph"><p>从事算法交易的投资公司应具备有效的系统与风险控制，确保交易系统具有韧性、有足够容量、设有适当交易限额，并防止发送错误订单或以可能导致混乱或滥用市场的方式运作。</p><footer>—— MiFID II 第 17 条；组织要求由 Commission Delegated Regulation (EU) 2017/589（RTS 6）具体化</footer></div><p><a href="/quant/sr-11-7-model-risk">SR 11-7</a> 写的是模型治理预期；落到算法交易的逐条义务，是 RTS 6。MiFID II（Directive 2014/65/EU）第 17 条给算法交易加了一层组织义务。欧盟委员会 2016 年 7 月 19 日的授权规则 (EU) 2017/589——市场所称 RTS 6——把这些义务写成可检查的条款：治理与人员、研发与生产隔离、符合性与压力测试、年度自评与验证、杀单功能、操纵监测、业务连续性、预交易控制、实时监控、事后控制，以及高频技术的订单记录。ESMA 在后续监管简报中重申：算法与算法交易的口径、外包与测试，是各国主管机关容易分叉、因而需要对齐的地方。本篇把 RTS 6 读成策略与工程的<strong>公开约束</strong>：控制是动作掩码与独立闸门，不是优化目标。它不提供如何设计更具侵略性的下单节奏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>算法交易把下单速度推到人工来不及逐笔判断。第 17 条担心的是错误订单、容量不足、无限额，以及策略以造成混乱或构成市场滥用的方式运行。RTS 6 不管「这套信号赚不赚钱」，管的是：谁对算法负责、上线前测过什么、盘中谁能停、限额是否在订单离开公司前生效。量化研究若只在回测里调参，会把这些控制当成事后可贴的标签；文本的顺序相反——没有通过测试与控制的算法，不应当出现在生产环境。</p><p>定义上要分开。投资决策算法决定买卖什么；执行算法在决策之后生成并提交订单或报价。RTS 6 序言与交易报告字段都承认这一划分。高频算法交易技术另有记录义务（第 28 条及附件表格）：提交后立即按指定字段记下每一笔订单细节。是否构成第 17 条的算法交易，以 MiFID II 的法定定义为准，不能用「我们只是把人工单拆细」自动豁免——若系统自动决定提交、修改或撤销，就进入组织要求的射程。</p><p><span class="marginnote">术语翻译：「投资决策算法」回答买什么、卖什么；「执行算法」只负责把已决定的单子拆开、改价、送出去。RTS 6 对两类都适用——判断标准不是它有没有观点，而是系统是否自动决定提交、修改或撤销订单；「拆单工具」也在射程内。</span></p><h3 id="生产与测试必须是两套环境" tabindex="-1">生产与测试必须是两套环境 <a class="header-anchor" href="#生产与测试必须是两套环境" aria-label="Permalink to &quot;生产与测试必须是两套环境&quot;">​</a></h3><p>第 7 条要求：对符合第 5 条若干准则的测试，在<strong>与生产分离</strong>、专用于算法系统开发与测试的环境中进行。第 10 条把压力测试放进年度自评：系统与第 12–18 条的程序控制应能承受订单流增加与市场压力，且测试本身不得影响生产。这直接约束研究—模拟—实盘的拓扑：用生产网关「试一下新参数」，是文本禁止的模式。符合性测试针对交易场所的接口与规则；压力与情景分析针对自身策略在高消息量、高延迟、行情缺口下是否仍守限额。ESMA 的监管简报强调外包开发并不转移测试责任。</p><p><span class="marginnote">年度自评（第 9 条）由风险管理职能撰写验证报告，并告知合规职能缺陷。没有独立风险职能时，义务落到第 23 条意义上的替代职能。自评不是营销材料：它要覆盖治理、控制、连续性以及与第 17 条的整体符合，并与业务的性质、规模、复杂度相称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 RTS 6 映射到交易系统，是一组硬约束，而不是一组可微惩罚。</p><p>预交易控制（第 15 条）对所有金融工具在订单进入时实施：价格项圈，自动阻挡或取消不符合价格参数的订单；最大订单价值；最大订单数量；最大消息限制，防止对订单簿提交、改单、撤单过多。已发往交易场所的订单须立即计入这些限额。策略若在模拟器里靠「多撤多改」维持队列，会在真实控制下触达消息上限被切断——这是约束改变可行集，应在回测里就关掉这类动作，而不是上线后惊讶。反复自动执行节流：同一算法策略重复执行达到预定次数后，系统自动禁用，直到指定人员重新启用。市场与信用风险限额须基于资本、清算安排、策略与风险容忍，并随价格与流动性变化调整。无权交易某工具的交易员订单应被自动阻挡。被预交易控制挡住、仍想提交的订单，只能在例外、临时、逐笔、并经风险职能核实与指定人员授权后放行。</p><p>杀单功能（第 12 条）要求能够立即取消发往任一或全部已连接交易场所的未成交订单，覆盖交易员、交易台以及适用时的客户来源，并能识别每笔订单对应的算法与责任人。这与内部<a href="/quant/trading-kill-switch">风控闸门</a>对齐，但 RTS 6 把它写成对主管机关与场所可展示的能力，而不是策略参数。实时监控（第 16 条）在发送订单的时段内，由负责该算法的交易员以及独立于该交易员的风险控制共同进行；告警应在相关事件后五秒内产生，并覆盖可能触发场所熔断的情况。事后控制与对账补上盘后的暴露与日志一致性。</p> \\[a_t\\in\\mathcal{A}_{\\mathrm{legal}}(s_t)\\cap\\mathcal{A}_{\\mathrm{pre}}(s_t),\\qquad \\mathcal{A}_{\\mathrm{pre}}=\\{\\,a:\\text{价格、数量、价值、消息速率均在限额内}\\,\\}. \\]<p>动作掩码属于第 15 条；策略网络或规则只在掩码内优化。把限额写进奖励再希望智能体学会不越界，与文本不符：控制应在提交前自动阻挡。</p>',16)),(t(),n(B,null,{default:e(()=>[l(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E7%AE%97%E6%B3%95%E7%94%9F%E6%88%90%E4%B8%80%E7%AC%94%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20CHK%7B%22%E4%BB%B7%E6%A0%BC%E3%80%81%E4%BB%B7%E5%80%BC%E3%80%81%E6%95%B0%E9%87%8F%E3%80%81%E6%B6%88%E6%81%AF%E9%80%9F%E7%8E%87%E5%9D%87%E5%9C%A8%E9%99%90%E9%A2%9D%E5%86%85%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20BLOCK%5B%22%E9%A2%84%E4%BA%A4%E6%98%93%E6%8E%A7%E5%88%B6%E8%87%AA%E5%8A%A8%E9%98%BB%E6%8C%A1%E6%88%96%E5%8F%96%E6%B6%88%22%5D%0A%20%20BLOCK%20--%3E%20ESC%7B%22%E4%BE%8B%E5%A4%96%E6%94%BE%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20ESC%20--%3E%7C%22%E9%A3%8E%E9%99%A9%E8%81%8C%E8%83%BD%E6%A0%B8%E5%AE%9E%20%2B%20%E6%8C%87%E5%AE%9A%E4%BA%BA%E5%91%98%E9%80%90%E7%AC%94%E6%8E%88%E6%9D%83%22%7C%20REL%5B%22%E4%B8%B4%E6%97%B6%E6%94%BE%E8%A1%8C%E5%B9%B6%E7%95%99%E7%97%95%22%5D%0A%20%20ESC%20--%3E%7C%22%E5%90%A6%E5%88%99%22%7C%20DEAD%5B%22%E8%AE%A2%E5%8D%95%E7%BB%88%E6%AD%A2%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20CNT%5B%22%E7%AB%8B%E5%8D%B3%E8%AE%A1%E5%85%A5%E9%99%90%E9%A2%9D%E5%B9%B6%E5%8F%91%E5%BE%80%E5%9C%BA%E6%89%80%22%5D%0A%20%20CNT%20--%3E%20MON%5B%22%E5%AE%9E%E6%97%B6%E7%9B%91%E6%8E%A7%E4%B8%8E%E4%BA%94%E7%A7%92%E5%86%85%E5%91%8A%E8%AD%A6%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<p><span class="marginnote">直觉类比：预交易控制是闸机，不是计分板。它不「越界后扣分提醒」，而是闸门直接关上、订单出不了公司。想放被挡下的单子，只能走人工例外通道——逐笔、临时、有人签字留痕，没有「这批先过、回头补手续」。</span></p><h3 id="操纵监测是另一条流水线" tabindex="-1">操纵监测是另一条流水线 <a class="header-anchor" href="#操纵监测是另一条流水线" aria-label="Permalink to &quot;操纵监测是另一条流水线&quot;">​</a></h3><p>第 13 条要求对经由其系统发生的全部交易活动（含客户）监测《市场滥用条例》(EU) No 596/2014 第 12 条意义上的潜在操纵，并维持自动监测系统：告警、报告、必要时可视化，覆盖全部订单，可按监管义务与自身策略变化调整，每年评估误报与漏报，并能在低延迟环境中事后回放。可疑活动走合规评估，必要时向场所报告或提交 STOR。这与预交易限额目的不同：限额防的是错误与混乱，监测防的是滥用。量化研究不应把监测规则的细节当成「如何避免被抓住」的攻略；公开义务是建立有效监测并跟进告警。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RTS 6 把算法交易拆成生命周期。开发：隔离环境、符合性与压力测试、上线授权。运行：预交易限额、实时双人监控、五秒级告警、可杀单。退出：业务连续性（第 14 条）包括关闭算法而不造成混乱、备份与未完成订单的替代安排，每年测试。治理（第 1–4 条）要求管理层理解算法、合规能接触杀单、人员具备技能。高频记录把微观订单史留成可审计对象。整条链的效果是：策略的状态空间被合法动作与限额切开，事故时有人能停、有日志能回放。</p><p>相称性贯穿文本：「性质、规模与复杂度」。小型、低频的算法仍要有控制，但压力情景与备份地点的具体形态可以更轻。不能把相称性读成「成交不频繁就没有第 17 条」。直接电子接入（DEA）与一般清算会员另有专节：提供接入的公司要对客户流施加自己的控制，不能把第 17 条的义务连同接入一起外包消失。</p><p><span class="marginnote">ESMA 2024 年对预交易控制的共同监管行动之后，简报强调各国对「什么算算法」仍可能不一致。实务上应按法定定义从宽登记：自动生成订单的执行器、做市报价引擎、智能路由，通常都在射程内。漏登记的代价是控制框架出现空洞，而不是获得监管优势。</span></p><h3 id="控制失败是-knight-一类事故的制度答案" tabindex="-1">控制失败是 Knight 一类事故的制度答案 <a class="header-anchor" href="#控制失败是-knight-一类事故的制度答案" aria-label="Permalink to &quot;控制失败是 Knight 一类事故的制度答案&quot;">​</a></h3><p>2012 年 Knight Capital 的错误部署表明：生产环境里并行的旧代码可以在数十分钟内造成巨大损失。RTS 6 并不点名该公司，但其测试隔离、上线控制、消息限额、杀单与实时监控，正是针对同一类操作风险。对量化台的含义是：参数发布、代码哈希、限额配置必须走变更控制；<a href="/quant/research-sim-prod">研究与实盘隔离</a>不是风格问题，是第 7 条与第 15 条的工程翻译。模型验证若按 <a href="/quant/sr-11-7-model-risk">SR 11-7</a> 做，管的是估计器是否错误或被误用；RTS 6 管的是交易系统是否会把错误估计变成扰乱市场的订单流。两套同时需要。</p><p><span class="marginnote">为什么重要：Knight 事故里，失效的旧代码在约 45 分钟内发出海量错单、损失约 4.6 亿美元，公司次日濒临破产被收购。RTS 6 的消息限额、五秒告警与杀单，正是为了让同类事故在分钟级被切断——每一项单独看都平常，合起来是「让任何人都能在来得及的时候停机」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RTS 6 适用于从事算法交易的投资公司，并经 MiFID II 第 1(5) 条延伸到某些无需按该指令授权、但是受监管市场或 MTF 成员的参与者。英国脱欧后有平行的国内文本，不能假设字句永远与欧盟官方公报一致。交易场所自己的成员规则（容量测试、取消比率）是另一层合同约束，常比 RTS 6 更细。本篇只讨论公开的组织要求如何限制策略的动作集与上线流程。</p><p>不要把预交易项圈设成与策略信号同一组可调超参，在样本内一起优化——那会在平静期学到过窄的项圈，在跳跃日要么拒掉全部对冲、要么放行本应阻挡的错单。限额应由独立风险职能按资本与清算安排设定。不要设计以制造虚假报价压力为目的的消息模式；第 13 条与 MAR 把那类行为放在滥用监测而非「执行优化」下。</p><p><span class="marginnote">杀单必须能在算法失控时使用，也必须能在关闭时不制造混乱（第 14(3) 条）。工程上这意味着撤单顺序、对冲残腿与向场所的通信要预先演练。把 kill 做成「删掉进程、订单留在簿上」，不符合「取消未成交订单」的定义。</span></p>',14)),(t(),n(B,null,{default:e(()=>[l(A,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20Dev%5B%22%E9%9A%94%E7%A6%BB%E7%8E%AF%E5%A2%83%E5%BC%80%E5%8F%91%22%5D%20--%3E%20Test%5B%22%E7%AC%A6%E5%90%88%E6%80%A7%20%2F%20%E5%8E%8B%E5%8A%9B%20%2F%20%E6%83%85%E6%99%AF%E6%B5%8B%E8%AF%95%22%5D%0A%20%20Test%20--%3E%20Auth%5B%22%E4%B8%8A%E7%BA%BF%E6%8E%88%E6%9D%83%22%5D%0A%20%20Auth%20--%3E%20Pre%5B%22%E9%A2%84%E4%BA%A4%E6%98%93%E6%8E%A7%E5%88%B6%3A%20%E4%BB%B7%E6%A0%BC%20%E4%BB%B7%E5%80%BC%20%E6%95%B0%E9%87%8F%20%E6%B6%88%E6%81%AF%22%5D%0A%20%20Pre%20--%3E%20Ven%5B%22%E5%8F%91%E5%BE%80%E4%BA%A4%E6%98%93%E5%9C%BA%E6%89%80%22%5D%0A%20%20Ven%20--%3E%20RT%5B%22%E5%AE%9E%E6%97%B6%E7%9B%91%E6%8E%A7%20%E2%89%A45%20%E7%A7%92%E5%91%8A%E8%AD%A6%22%5D%0A%20%20RT%20--%3E%20Kill%5B%22%E7%AC%AC%2012%20%E6%9D%A1%E6%9D%80%E5%8D%95%E5%8A%9F%E8%83%BD%22%5D%0A%20%20Ven%20--%3E%20Sur%5B%22%E7%AC%AC%2013%20%E6%9D%A1%E6%93%8D%E7%BA%B5%E7%9B%91%E6%B5%8B%22%5D%0A%20%20Year%5B%22%E7%AC%AC%209%20%E6%9D%A1%E5%B9%B4%E5%BA%A6%E8%87%AA%E8%AF%84%E4%B8%8E%E9%AA%8C%E8%AF%81%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20Dev%0A%20%20Year%20--%3E%20Pre%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("h2",{id:"小结",tabindex:"-1"},[i("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[5]||(E[5]=a("ul",null,[a("li",null,"RTS 6（(EU) 2017/589）把 MiFID II 第 17 条落成治理、测试、限额、监控、杀单与记录等组织要求。"),a("li",null,"测试必须离开生产；年度自评由风险职能验证并告知合规。"),a("li",null,"预交易控制是提交前的硬掩码：价格项圈、最大价值与数量、消息上限、重复执行节流。"),a("li",null,"杀单须能识别算法与责任人并取消未成交订单；实时告警时限为五秒。"),a("li",null,"操纵监测按 MAR 另建流水线，与防错单的限额不是同一套系统。"),a("li",null,"控制由独立风险职能设定，不与策略参数一起样本内优化。"),a("li",null,"出处：Directive 2014/65/EU Art. 17；Commission Delegated Regulation (EU) 2017/589；ESMA Supervisory Briefing on Algorithmic Trading in the EU；Regulation (EU) No 596/2014 Art. 12, 16。")],-1))])}const f=s(d,[["render",h]]);export{c as __pageData,f as default};
